import { strict as assert } from 'node:assert';

async function moduleFile(name: string) {
  return new WebAssembly.Module(await Bun.file(`${import.meta.dir}/${name}.wasm`).arrayBuffer());
}
function fn(instance: WebAssembly.Instance, name: string): CallableFunction {
  const value = instance.exports[name];
  assert.equal(typeof value, 'function');
  if (typeof value !== 'function') throw new Error(`Missing ${name}`);
  return value;
}

const memory = new WebAssembly.Memory({ initial: 1, maximum: 3, shared: true });
const first = memory.buffer;
assert(first instanceof SharedArrayBuffer);
assert.equal(memory.buffer, first);
const words = new Int32Array(first);
const imported = await moduleFile('imported');
let callback = () => { Atomics.store(words, 0, 31); };
const a = new WebAssembly.Instance(imported, { env: { memory, observe: () => callback() } });
const b = new WebAssembly.Instance(imported, { env: { memory, observe: () => callback() } });
assert.equal(a.exports.memory, memory);
assert.equal(a.exports.alias, memory);
assert.equal(b.exports.memory, memory);
Atomics.store(words, 0, 7);
assert.equal(fn(a, 'read')(), 7);
assert.equal(fn(a, 'add')(5), 7);
assert.equal(Atomics.load(words, 0), 12);
fn(b, 'write')(19);
assert.equal(Atomics.load(words, 0), 19);
assert.equal(fn(a, 'wait')(20, 0n), 1);
assert.equal(fn(a, 'wait')(19, 0n), 2);
assert.equal(Atomics.wait(words, 0, 20, 0), 'not-equal');
assert.equal(Atomics.wait(words, 0, 19, 0), 'timed-out');
assert.equal(Atomics.notify(words, 0, 1), 0);
assert.equal(fn(a, 'notify')(), 0);
assert.equal(memory.grow(1), 1);
const second = memory.buffer;
assert(second instanceof SharedArrayBuffer);
assert.notEqual(first, second);
assert.equal(first.byteLength, 65536);
assert.equal(second.byteLength, 131072);
assert.equal(new Int32Array(second)[16384], 0);
Atomics.store(words, 0, 23);
assert.equal(fn(b, 'read')(), 23);
assert.equal(fn(a, 'grow')(1), 2);
assert.equal(memory.buffer.byteLength, 196608);
assert.equal(first.byteLength, 65536);
assert.equal(second.byteLength, 131072);
assert.equal(fn(a, 'grow')(1), -1);
assert.throws(() => memory.grow(1), RangeError);
assert.equal(memory.grow(0), 3);
const current = memory.buffer;
assert.equal(memory.buffer, current);
callback = () => { fn(b, 'write')(37); };
fn(a, 'callback')();
assert.equal(Atomics.load(words, 0), 37);
const thrown = { exact: 'original object' };
callback = () => { throw thrown; };
assert.throws(() => fn(a, 'callback')(), error => error === thrown);
callback = () => { fn(b, 'write')(41); };
const start = await moduleFile('start');
new WebAssembly.Instance(start, { env: { memory, observe: () => callback() } });
assert.equal(fn(a, 'read')(), 41);
callback = () => { fn(b, 'write')(43); throw thrown; };
assert.throws(() => new WebAssembly.Instance(start, { env: { memory, observe: () => callback() } }), error => error === thrown);
assert.equal(fn(a, 'read')(), 43);
const trap = await moduleFile('start-trap');
assert.throws(() => new WebAssembly.Instance(trap), WebAssembly.RuntimeError);
assert.throws(() => new WebAssembly.Instance(imported, { env: { memory: new WebAssembly.Memory({ initial: 1, maximum: 3 }), observe() {} } }), WebAssembly.LinkError);
assert.throws(() => fn(a, 'misaligned')(), WebAssembly.RuntimeError);
assert.throws(() => fn(a, 'oob')(), WebAssembly.RuntimeError);
const defined = new WebAssembly.Instance(await moduleFile('defined'));
assert(defined.exports.memory instanceof WebAssembly.Memory);
assert(defined.exports.memory.buffer instanceof SharedArrayBuffer);
assert.equal(fn(defined, 'read')(), 42);
assert.equal(fn(defined, 'grow')(1), 1);
const zero = new WebAssembly.Memory({ initial: 0, maximum: 1, shared: true });
const another = new WebAssembly.Memory({ initial: 0, maximum: 1, shared: true });
assert.notEqual(zero.buffer, another.buffer);
assert.equal(zero.buffer.byteLength, 0);
assert.equal(zero.grow(1), 0);
assert.equal(zero.buffer.byteLength, 65536);
assert.throws(() => new WebAssembly.Memory({ initial: 0, shared: true }), TypeError);
assert.equal(fn(a, 'read')(), 43);
console.log('shared-wasm-memory: pass');
